import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.Buc7gXeZ.js";const A=JSON.parse('{"title":"常见问题","description":"FAQ：邀请、审核、播放、API、限流等常见问题解答。","frontmatter":{"title":"常见问题","description":"FAQ：邀请、审核、播放、API、限流等常见问题解答。","order":61,"group":"meta"},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),n={name:"faq.md"};function s(d,e,c,i,p,l){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题（FAQ）&quot;">​</a></h1><h2 id="邀请与注册" tabindex="-1">邀请与注册 <a class="header-anchor" href="#邀请与注册" aria-label="Permalink to &quot;邀请与注册&quot;">​</a></h2><p><strong>Q：现在注册需要邀请码吗？</strong><br> A：取决于当前站点的运行配置。打开登录注册页面时，表单会动态提示是否需要填写邀请码。活动期间平台可能会临时开放免邀请公开注册。</p><p><strong>Q：在哪里获取我的邀请码？</strong><br> A：已注册用户可在个人中心「邀请管理」页面（<code>/invites</code>）查看自己的专属 <code>MF-</code> 永久邀请码与剩余生成配额。</p><h2 id="浏览与媒体" tabindex="-1">浏览与媒体 <a class="header-anchor" href="#浏览与媒体" aria-label="Permalink to &quot;浏览与媒体&quot;">​</a></h2><p><strong>Q：游客能浏览哪些内容？</strong><br> A：全量基础元数据（作品、发行版、创作者、分类标签、实体图谱、全文搜索及社区公开讨论）。点击播放音视频、下载原档、上传资源或在社区发帖时，系统会引导登录。</p><p><strong>Q：为什么媒体资源提示无法播放或无权限？</strong><br> A：媒体资源（原档与预览切片）受到访问控制保护，仅对已登录用户开放。请确认当前处于登录状态；若在外部脚本或第三方客户端中访问，请确保已配置有效的个人访问令牌（PAT）。</p><p><strong>Q：封面为什么无法正常显示？</strong><br> A：平台对封面链接有安全性校验机制。建议使用系统内置的本地文件上传，或填写可信图床的直接图片链接。</p><h2 id="编辑与审核" tabindex="-1">编辑与审核 <a class="header-anchor" href="#编辑与审核" aria-label="Permalink to &quot;编辑与审核&quot;">​</a></h2><p><strong>Q：为什么提交的词条或修改被退回？</strong><br> A：常见原因包括：缺少修改说明（Edit Note）、缺少参考来源链接（Source URLs）、标题命名或图谱关联有误、或者属于重复创建。根据考据员在审核意见中给出的提示修正后重新提交即可。</p><p><strong>Q：如何避免创建重复的词条？</strong><br> A：在新建词条前，请先在顶部搜索栏输入作品原名、罗马音、常见译名或唱片编号进行充分检索，优先完善与复用已有条目。</p><h2 id="开发者与-api" tabindex="-1">开发者与 API <a class="header-anchor" href="#开发者与-api" aria-label="Permalink to &quot;开发者与 API&quot;">​</a></h2><p><strong>Q：未登录（匿名访问）支持通过程序调用哪些数据？</strong><br> A：平台所有公开元数据（作品目录、实体详情、检索服务、分类标签、图谱关系及社区讨论等）均支持公开只读调用；涉及内容写入、媒体上传、原档下载等敏感操作则必须携带有效的个人访问令牌（PAT）。</p><p><strong>Q：为什么通过 API 写入数据时提示错误？</strong><br> A：请确认客户端请求头中已包含规范的 <code>User-Agent</code>（如 <code>MyApp/1.0 (you@example.com)</code>），并在请求体中附带了 <code>edit_note</code>（修改说明）或 <code>source_urls</code>（参考来源）。详情请查阅 <a href="/docs/api-overview">开发者 API 概览</a>。</p><p><strong>Q：平台接口调用频率限制是多少？</strong><br> A：匿名未登录请求上限为 60 次/分钟，登录及 PAT 认证请求上限为 600 次/分钟。响应头包含限流状态信息，触发限流时请适当退避重试。</p><h2 id="部署与运维" tabindex="-1">部署与运维 <a class="header-anchor" href="#部署与运维" aria-label="Permalink to &quot;部署与运维&quot;">​</a></h2><p><strong>Q：部署时 OpenSearch 未启动会影响正常使用吗？</strong><br> A：系统具备自动降级机制，搜索功能会自动降级为数据库检索，不影响全站的基础浏览与编目。公网部署时建议将 OpenSearch 置于内网环境或开启安全认证。</p><p><strong>Q：文档站如何访问与本地预览？</strong><br> A：线上环境可通过 <code>/docs/</code> 直接访问（由网关自动代理）；本地独立开发可在 <code>docs-site</code> 目录下运行 <code>npm run dev</code> 进行预览。</p>',18)])])}const g=r(n,[["render",s]]);export{A as __pageData,g as default};
